def comps(g, target=None):
    seen=set(); n=0; sizes=[]
    for r in range(7):
        for c in range(7):
            v=g[r][c]
            if (v!=0 if target is None else v==target) and (r,c) not in seen:
                n+=1; st=[(r,c)]; seen.add((r,c)); s=0
                while st:
                    a,b=st.pop(); s+=1
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        p,q=a+da,b+db
                        if 0<=p<7 and 0<=q<7 and (p,q) not in seen and ((g[p][q]!=0 if target is None else g[p][q]==target)):
                            seen.add((p,q)); st.append((p,q))
                sizes.append(s)
    return n, sorted(sizes, reverse=True)
